import Foundation

// v1.3 Camera Profiles Phase B-3 (V-Log) and Phase C (S-Log3) accuracy gate.
// Loads the reference fixtures generated by the per-curve `encode-ramp.py`
// scripts and asserts that `FilmtoneSourceProfileMath` matches them within
// the D-CP5 tolerance budget. A drift beyond budget MUST fail this script
// (silent fallback / fixture regeneration in CI is forbidden — the fixture
// is only regenerated locally and committed).

// MARK: - Test harness

struct SourceProfileMathCheckError: LocalizedError {
    let message: String
    var errorDescription: String? { message }
}

func expect(_ condition: @autoclosure () -> Bool, _ message: String) throws {
    if !condition() {
        throw SourceProfileMathCheckError(message: message)
    }
}

// MARK: - Fixture decode

private struct LinearizationSample: Decodable {
    let vEncoded: Double
    let lLinear: Double
}

private struct DlogMacbethPatch: Decodable {
    let index: Int
    let dlogEncoded: [Double]
    let rec709EncodedExpected: [Double]
